import React from "react";
import {PiCardProps} from "@pihanga2/core";
import {Graphin} from "@antv/graphin";

import {
  NodeEvent,
  type GraphOptions,
  type Graph,
} from "@antv/g6";

import {GraphinProps} from "./graphin.types";
import clsx from "clsx";
import {cloneDeep, merge} from "lodash";
import {TooltipComponent} from "./tooltip.component";

export const GraphinComponent = (
  props: PiCardProps<GraphinProps>,
): React.ReactNode => {
  const {cardName, data, options, tooltip, style, className, _cls} = props;

  const handleReady = (graph: Graph) => {
    console.log("Graph ready:", graph);

    // Add event handlers
    graph.on(NodeEvent.CLICK, (evt) => {
      console.log("Node clicked:", evt);
    });

    graph.on("edge:click", (evt) => {
      console.log("Edge clicked:", evt);
    });
  };

  // console.log("AREA", area)
  const _style = {
    // display: "grid",
    // gridGap: template.gap || "10px",
    // height,
    // margin,
    // width: "100%",

    display: "flex",
    width: "100%",
    ...style?.root,
  };

  const defOptions: GraphOptions = {
    data,
    autoResize: true,
    node: {
      style: {
        labelText: (d) => {
          return (d.data?.displayName || d.id) as string;
        },
        lod: {
          0: {labelFontSize: 10}, // Zoomed out: smaller font
          1: {labelFontSize: 12}, // Normal: standard font
          2: {labelFontSize: 6}, // Zoomed in: reduce font size so it doesn't overwhelm
        },
        // labelFontSize: 12, // This is your "Base" size
        // labelWordWrap: true,
        // labelWordWrapWidth: 100, // Limits the horizontal growth
      },
      // palette: {
      //   type: "group",
      //   field: "cluster",
      // },
    },
    // layout: {
    //   type: "force", // The layout engine type
    //   preventOverlap: true, // Parameters specific to the 'force' engine
    //   nodeSize: 30,
    //   linkDistance: 100,
    // },
    layout: {
      type: "force-atlas2",
      preventOverlap: true,
      kr: 20,
      // center: [250, 250],
    },
    behaviors: [
      "drag-canvas",
      "drag-element",
      // "zoom-canvas",
      {
        type: "auto-adapt-label",
        enableAnimation: true,
        throttle: 100,
        padding: 0,
      },
      {
        type: "zoom-canvas",
        id: "zoom-canvas-1",
        // trigger: {
        //   zoomIn: ["Control", "+"], // Zoom in shortcut
        //   zoomOut: ["Control", "-"], // Zoom out shortcut
        //   reset: ["Control", "0"], // Reset zoom ratio shortcut
        // },
        // trigger: ["Control"],
        fixSelectedItems: {fixLabel: true},
      },
    ],
    animation: true,
  };

  const mergedOptions = merge(cloneDeep(defOptions), options);
  return (
    <div
      style={_style}
      className={clsx(_cls("root"), className)}
      data-pihanga={cardName}
    >
      <Graphin
        options={mergedOptions}
        onReady={handleReady}
        style={{width: "inherit"}}
      >
        {tooltip && (
          <TooltipComponent contentCards={tooltip} parentCard={cardName} />
        )}
      </Graphin>
    </div>
  );
};

import {createCardDeclaration, PiCardDef} from "@pihanga2/core";
import {GraphData, GraphOptions} from "@antv/g6";

export const GRAPHIN_CARD = "graphin";
export const Graphin = createCardDeclaration<GraphinProps>(GRAPHIN_CARD);

export type GraphinProps = {
  data: GraphData;
  options?: Partial<Omit<GraphOptions, "data">>;
  tooltip?: GraphinTooltip;
  style?: {
    root?: React.CSSProperties;
    item?: React.CSSProperties;
  };
  className?: string;
};

export type GraphinTooltip = {
  node?: PiCardDef;
  edge?: PiCardDef;
};

import {registerCardComponent} from "@pihanga2/core";

import {GraphinComponent} from "./graphin.component";
import {GRAPHIN_CARD} from "./graphin.types";

export * from "./graphin.types";
export type {TooltipContext} from "./tooltip.component";

registerCardComponent({
  name: GRAPHIN_CARD,
  component: GraphinComponent,
});

import {useState, useEffect} from "react";
import {useGraphin} from "@antv/graphin";
import type {IPointerEvent} from "@antv/g6";
import type {DisplayObject} from "@antv/g";
import {Target} from "@antv/g6/lib/types";
import {GraphinTooltip} from "@/cards/graphin/graphin.types";
import {Card} from "@pihanga2/core";

export type TooltipContext<T = Record<string, unknown>> = {
  isEdge?: boolean;
  elementID?: string;
  elementData?: T;
};

type tooltipState = TooltipContext & {
  visible: boolean;
  x: number;
  y: number;
};

export function TooltipComponent(props: {
  contentCards: GraphinTooltip;
  parentCard: string;
}): React.ReactNode {
  const {contentCards, parentCard} = props;
  const {graph, isReady} = useGraphin();
  const [tooltip, setTooltip] = useState<tooltipState>({
    visible: false,
    x: 0,
    y: 0,
  });

  useEffect(() => {
    if (!isReady || !graph) return;

    // Try different event name formats
    const handleNodePointerEnter = (
      evt: IPointerEvent<DisplayObject & Target>,
    ) => {
      const nodeId = evt.target.id;
      const nodeData = graph.getNodeData(nodeId);

      setTooltip({
        visible: true,
        x: evt.canvas.x || evt.x,
        y: evt.canvas.y || evt.y,
        isEdge: true,
        elementID: nodeId,
        elementData: nodeData.data,
      });
    };

    const handleNodePointerLeave = () => {
      console.log("Pointer leave event");
      setTooltip({
        visible: false,
        x: 0,
        y: 0,
        isEdge: undefined,
        elementID: undefined,
        elementData: undefined,
      });
    };

    // Listen to G6 events
    console.log(">>> tooltip effect", graph);
    graph.on("node:pointerenter", handleNodePointerEnter);
    graph.on("node:pointerleave", handleNodePointerLeave);

    return () => {
      graph.off("node:pointerenter", handleNodePointerEnter);
      graph.off("node:pointerleave", handleNodePointerLeave);
    };
  }, [graph, isReady]);

  if (!contentCards.node) return null;
  if (!tooltip.visible) return null;

  return (
    <div
      style={{
        position: "absolute",
        left: tooltip.x + 10,
        top: tooltip.y + 10,
        background: "white",
        padding: "12px",
        borderRadius: "4px",
        boxShadow: "0 2px 8px rgba(0,0,0,0.15)",
        pointerEvents: "none",
        zIndex: 1000,
      }}
    >
      {/* <h4 style={{margin: "0 0 8px 0"}}>{tooltip.elementID}</h4> */}
      <Card cardName={contentCards.node} parentCard={parentCard} {...tooltip} />
    </div>
  );
}
